import{_ as t,o as d,c as o,a0 as r}from"./chunks/framework.K3sFe4KB.js";const u=JSON.parse('{"title":"Providers","description":"","frontmatter":{},"headers":[],"relativePath":"reference/providers.md","filePath":"reference/providers.md"}'),a={name:"reference/providers.md"};function c(i,e,s,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h1><p><code>--provider</code> selects the adapter: <code>fake</code> (default) or <code>google</code>. Both sit behind the same <code>CalendarProvider</code> port; the planner checks each provider&#39;s declared capabilities at plan time and emits warnings or errors for unsupported desired states.</p><h2 id="fake" tabindex="-1"><code>fake</code> <a class="header-anchor" href="#fake" aria-label="Permalink to &quot;`fake`&quot;">​</a></h2><p>A file-backed fake for tests, demos, and development — <strong>test/demo only</strong>. Serialises its whole backend to <code>.cicada/fake-provider.json</code> after every mutation, so separate <code>cicada</code> invocations share one &quot;provider&quot; and hand-edits simulate out-of-band changes. Reports permissive capabilities (everything supported).</p><h2 id="google" tabindex="-1"><code>google</code> <a class="header-anchor" href="#google" aria-label="Permalink to &quot;`google`&quot;">​</a></h2><p>Google Calendar API v3, with Google Meet as its conferencing kind — <code>conferencing: meet</code> is an intent the planner resolves, not a URL.</p><h3 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Value</th></tr></thead><tbody><tr><td><code>maxAttendees</code></td><td>200</td></tr><tr><td><code>maxReminders</code></td><td>5</td></tr><tr><td><code>reminderKinds</code></td><td><code>popup</code>, <code>email</code></td></tr><tr><td>Recurrence frequencies</td><td>all seven (<code>DAILY</code>…<code>SECONDLY</code>)</td></tr><tr><td>Ordinal <code>byDay</code>, <code>byMonthDay</code>, <code>byMonth</code>, raw RRULE</td><td>yes</td></tr><tr><td><code>conferencingKinds</code></td><td><code>meet</code></td></tr><tr><td><code>can_suppress_notifications</code></td><td>yes (<code>sendUpdates</code>)</td></tr><tr><td><code>supports_free_busy</code></td><td>yes</td></tr><tr><td><code>supports_tagging</code></td><td>yes (<code>extendedProperties.private</code>)</td></tr><tr><td><code>supports_conditional_writes</code></td><td>yes (etag → <code>If-Match</code>)</td></tr></tbody></table><p>Retried with exponential backoff at the HTTP layer; 429/5xx surface as <code>Transient</code> errors.</p><h3 id="auth" tabindex="-1">Auth <a class="header-anchor" href="#auth" aria-label="Permalink to &quot;Auth&quot;">​</a></h3><p>Credentials resolve in this order (first match wins):</p><table tabindex="0"><thead><tr><th>Priority</th><th>Source</th><th>Variables</th></tr></thead><tbody><tr><td>1</td><td>Service-account key file path</td><td><code>CICADA_GOOGLE_SERVICE_ACCOUNT_JSON</code> or <code>GOOGLE_APPLICATION_CREDENTIALS</code></td></tr><tr><td>2</td><td>Static access token (no refresh; ~1h expiry)</td><td><code>CICADA_GOOGLE_ACCESS_TOKEN</code></td></tr><tr><td>3</td><td>OAuth installed-app client + refresh token</td><td><code>CICADA_GOOGLE_CLIENT_ID</code> + <code>CICADA_GOOGLE_CLIENT_SECRET</code>; refresh from <code>CICADA_GOOGLE_REFRESH_TOKEN</code> or the stored token</td></tr><tr><td>4</td><td>Persisted service-account key</td><td><code>google/service-account</code> in the secrets store (written by <code>cicada provider add google --service-account</code>)</td></tr></tbody></table><p>Optional:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>CICADA_GOOGLE_SUBJECT</code></td><td>Domain-wide delegation <code>sub</code> for service-account JWT</td></tr><tr><td><code>CICADA_GOOGLE_TOKEN_URL</code></td><td>Token endpoint override (tests)</td></tr><tr><td><code>CICADA_SECRETS_DIR</code></td><td>Secrets directory override</td></tr></tbody></table><h3 id="cicada-provider-add-google" tabindex="-1"><code>cicada provider add google</code> <a class="header-anchor" href="#cicada-provider-add-google" aria-label="Permalink to &quot;`cicada provider add google`&quot;">​</a></h3><ul><li><strong>OAuth</strong> (no flag): needs a client id/secret (flags or env). Prints the consent URL (<code>calendar</code> scope, offline access); a loopback listener captures the code, or the code/redirect URL is pasted. The refresh token is stored at <code>google/refresh-token</code> in the secrets store.</li><li><strong><code>--service-account key.json</code></strong>: validates and persists the key at <code>google/service-account</code> — the priority-4 fallback above. Share the target calendar with the account&#39;s <code>client_email</code>.</li></ul><p>Secrets live at <code>$CICADA_SECRETS_DIR</code>, else <code>$XDG_STATE_HOME/cicada/secrets</code>, else <code>~/.local/state/cicada/secrets</code> — directory <code>0700</code>, files <code>0600</code>, key names URL-encoded (<code>google%2Frefresh-token</code>).</p><h3 id="binding" tabindex="-1">Binding <a class="header-anchor" href="#binding" aria-label="Permalink to &quot;Binding&quot;">​</a></h3><p><code>metadata.calendarId</code> in YAML wins, then the recorded binding in state, then <code>primary</code>. cicada reconciles existing remote calendars — it does not provision them.</p><h2 id="future-providers" tabindex="-1">Future providers <a class="header-anchor" href="#future-providers" aria-label="Permalink to &quot;Future providers&quot;">​</a></h2><p>Teams, CalDAV and others arrive via the same <code>CalendarProvider</code> port (list/get/create/update/delete, <code>findByTag</code>, <code>freeBusy</code>, capabilities) — adapters, not core changes.</p>',21)])])}const f=t(a,[["render",c]]);export{u as __pageData,f as default};
